def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if no_water_days >= 1 or hp <= 3:
            safe_bid = min(budget, DAILY_SALARY * 0.75)
        return float(max(0.0, safe_bid))

    total_agents = 1 + len(alive)
    total_demand_units = WATER_REQ * total_agents
    scarcity = total_demand_units / max(1.0, supply)

    prev_bids = []
    prev_high = 0.0
    prev_avg = 0.0
    aggressive_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > prev_high:
                prev_high = float(bid)
            if float(bid) >= DAILY_SALARY * 1.2:
                aggressive_count += 1
    if prev_bids:
        prev_avg = sum(prev_bids) / len(prev_bids)

    low_supply = supply <= 17
    high_supply = supply >= 22
    urgent = (no_water_days >= 1) or (hp <= 3)
    very_urgent = (no_water_days >= 2) or (hp <= 2)

    base = DAILY_SALARY * 0.52

    if scarcity >= 3.0:
        base = DAILY_SALARY * 1.05
    elif scarcity >= 2.5:
        base = DAILY_SALARY * 0.88
    elif scarcity >= 2.0:
        base = DAILY_SALARY * 0.72
    else:
        base = DAILY_SALARY * 0.48

    if low_supply:
        base += 10.0
    if high_supply:
        base -= 8.0

    if prev_bids:
        if prev_high >= 120:
            if urgent:
                base = max(base, prev_avg + 3.0)
            else:
                base = min(base, DAILY_SALARY * 0.45)
        elif prev_high >= 90:
            base = max(base, min(prev_high + 2.0, DAILY_SALARY * 1.15))
        else:
            base = max(base, prev_high + 1.5)

    if aggressive_count >= 1 and not urgent:
        base -= 6.0

    if urgent:
        base = max(base, DAILY_SALARY * 0.92)
    if very_urgent:
        base = max(base, DAILY_SALARY * 1.18)

    if day >= 8:
        base += 8.0
    if day >= 9 and hp <= 5:
        base += 10.0

    reserve_floor = 0.0
    remaining_days = max(0, 10 - int(day))
    if remaining_days > 0 and not urgent:
        reserve_floor = remaining_days * DAILY_SALARY * 0.18

    max_affordable = max(0.0, budget - reserve_floor)
    if urgent:
        max_affordable = budget

    bid = min(base, max_affordable)

    if bid < 0:
        bid = 0.0
    if urgent and bid < DAILY_SALARY * 0.75:
        bid = min(budget, DAILY_SALARY * 0.75)

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        return float(min(my_status['budget'], DAILY_SALARY * 0.8))

    avg_prev = sum(prev_bids) / len(prev_bids)
    target_bid = avg_prev * 1.05

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], DAILY_SALARY * 1.5))

    if supply < WATER_REQ * (len(alive_opponents) + 1):
        return float(min(my_status['budget'], target_bid * 1.2))

    return float(min(my_status['budget'], target_bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = {aid: opp for aid, opp in opponents_status.items() if opp['alive']}
    previous_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            previous_bids.append(trace['bid'])
    if previous_bids:
        sorted_bids = sorted(previous_bids)
        # target to outbid the second highest (if at least 2 opponents)
        if len(sorted_bids) >= 2:
            target = sorted_bids[-2] + 1.5
        else:
            target = sorted_bids[-1] + 0.5
    else:
        target = DAILY_SALARY * 0.6
    # Adjust based on own HP
    if my_status['hp'] <= 3:
        target = max(target, DAILY_SALARY * 0.8)
    # Cap by budget and max bid
    bid = min(my_status['budget'], target, DAILY_SALARY * 1.0)
    # Ensure we bid at least something if we are desperate
    if my_status['hp'] <= 2 and my_status['budget'] > 0:
        bid = max(bid, DAILY_SALARY * 0.5)
    return max(0, bid)
